package com.gomgomapps.math.core;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;
public class ColumnProductTest {
 @Test public void all630PublicProductsHaveCarryStepsAndNoTransfer(){Set<String> signatures=new HashSet<>();for(int a=10;a<=99;a++)for(int b:List.of(0,1,2,3,4,5,8)){Question q=ColumnProduct.make(a,b);assertTrue(signatures.add(q.signature()));q.answers=new String[]{"poison"};assertTrue(new Checker().check(q,List.of(),List.of(""+(a*b))).correct());assertEquals(Checker.Status.WRONG_ANSWER,new Checker().check(q,List.of(),List.of(""+(a*b+1))).status);int ones=a%10*b,tens=a/10*b+ones/10;int[] expected={a%10,a/10,b,ones,ones%10,ones/10,tens,a*b};HelpPlan p=HelpPlan.forQuestion(q);assertEquals(8,p.size());assertFalse(p.canTransfer());for(int i=0;i<8;i++)assertTrue(p.step(i).accepts(""+expected[i]));assertEquals(a*b,tens*10+ones%10);assertTrue(q.choices.isEmpty());}assertEquals(630,signatures.size());}
 @Test public void actualSupplyExhaustsBeforeOldestAndIsYear3(){var limits=GlobalCurriculum.limits("england-primary-2021-v1",ColumnProduct.ID,3);Generator g=new Generator(new Random(132));List<String> history=new ArrayList<>();for(int i=0;i<630;i++){Question q=g.next(ColumnProduct.ID,history,true,limits);assertFalse(history.contains(q.signature()));history.add(q.signature());assertTrue(limits.allows(q));assertTrue(q.choices.isEmpty());}assertEquals(history.get(0),g.next(ColumnProduct.ID,history,false,limits).signature());Learning.Profile p=new Learning.Profile();GlobalCurriculum.chooseCountry(p,"GB");GlobalCurriculum.choosePack(p,"england-primary-2021-v1");assertTrue(GlobalCurriculum.pack(p).inGrade(ColumnProduct.ID,3));assertFalse(GlobalCurriculum.pack(p).inGrade(ColumnProduct.ID,2));}
 @Test public void malformedPublicOperandsCannotUseAnswerKeys(){for(String prompt:List.of("9 × 8","100 × 8","27 × 9","27 × -1","27 × 8 = 216")){Question q=ColumnProduct.make(27,8);q.prompt=prompt;assertNull(ColumnProduct.read(q));assertFalse(new Checker().check(q,List.of(),List.of("216")).correct());}}
}
